import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"豐","description":"周易正义 - 豐","frontmatter":{"title":"豐","description":"周易正义 - 豐"},"headers":[],"relativePath":"zh/classics/zhengyi/055.md","filePath":"zh/classics/zhengyi/055.md"}'),l={name:"zh/classics/zhengyi/055.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>雷火丰</p></blockquote><blockquote><p>卦辞：亨，王假之；勿忧，宜日中。</p></blockquote><blockquote><p>彖曰：丰，大也。明以动，故丰。王假之，尚大也。勿忧宜日中，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎，况于鬼神乎。</p></blockquote><h1 id="豐" tabindex="-1">豐 <a class="header-anchor" href="#豐" aria-label="Permalink to “豐”">​</a></h1><p>王弼：大而亨者，王之所至。</p><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“丰，亨”者，“丰”，卦名也，《彖》及《序卦。皆以“大”训“丰”也，然则丰者，多大之名，盈足之义，财多德大，故谓之为丰。德大则无所不容，财多则无所不齐。无所拥碍谓之为“亨”，故曰“丰，亨”。“王假之”者，假，至也，丰亨之道，王之所尚，非有王者之德，不能至之，故曰“王假之”也。</p><h3 id="勿忧-宜日中。-​" tabindex="-1">勿忧，宜日中。 ​ <a class="header-anchor" href="#勿忧-宜日中。-​" aria-label="Permalink to “勿忧，宜日中。 ​”">​</a></h3><p>王弼：丰之为义，阐弘微细，通夫隐滞者也，为天下之主，而令微隐者不亨，忧未巳也，故至“丰亨”，乃得勿忧也。用夫丰亨不忧之德，宜处天中，以偏照者也，故曰“宜日中”也。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：勿，无也。王能至於丰亨，乃得无复忧虑，故曰“勿忧也”。用夫丰亨无忧之德，然后可以君临万国，遍照四方，如日中之时，遍照天下，故曰“宜日中”也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="丰-大也。-​" tabindex="-1">丰，大也。 ​ <a class="header-anchor" href="#丰-大也。-​" aria-label="Permalink to “丰，大也。 ​”">​</a></h3><p>王弼：音阐大之大也。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>“彖曰：丰，大也”。○正义曰：“丰，大也”者，释卦名，正是弘大之义也。○注“音阐大之大也”。○正义曰：阐者，弘广之言，凡物之大，其有二种，一者自然之大，一者由人之阐弘使大。“丰”之为义，既阐弘微细，则丰之称大，乃阐大之大，非自然之大，故音之也。</p><h3 id="明以动-故丰。王假之-尚大也。-​" tabindex="-1">明以动，故丰。王假之，尚大也。 ​ <a class="header-anchor" href="#明以动-故丰。王假之-尚大也。-​" aria-label="Permalink to “明以动，故丰。王假之，尚大也。 ​”">​</a></h3><p>王弼：大者王之所尚，故至之也。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“动故丰”者，此就二体，释卦得名，为丰之意，动而不明，未能光大资明以动，乃能致丰，故曰“明以动故丰”也。“王假之，尚大也”者，丰大之道，王所崇尚，所以王能至之，以能尚大故也。</p><h3 id="勿忧-宜日中-宜照天下也。-​" tabindex="-1">“勿忧，宜日中”，宜照天下也。 ​ <a class="header-anchor" href="#勿忧-宜日中-宜照天下也。-​" aria-label="Permalink to ““勿忧，宜日中”，宜照天下也。 ​”">​</a></h3><p>王弼：以勿忧之德，故宜照天下也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：日中之时，遍照天下，王无忧虑，德乃光被，同於日中之盈，故曰“勿忧，宜日中，宜照天下也”。</p><h3 id="日中则昃-月盈则食-天地盈虚-与时消息-而况於人乎-况於鬼神乎-​" tabindex="-1">日中则昃，月盈则食，天地盈虚，与时消息，而况於人乎？况於鬼神乎？ ​ <a class="header-anchor" href="#日中则昃-月盈则食-天地盈虚-与时消息-而况於人乎-况於鬼神乎-​" aria-label="Permalink to “日中则昃，月盈则食，天地盈虚，与时消息，而况於人乎？况於鬼神乎？ ​”">​</a></h3><p>王弼：丰之为用，困於昃食者也。施於未足则尚丰，施於巳盈则方溢，不可以为常，故具陈消息之道者也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：此孔子因丰设戒，以上言王者以丰大之德，照临天下，同於日中。然盛必有衰，自然常理。日中至盛，过中则昃；月满则盈，过盈则食。天之寒暑往来，地之陵谷迁贸，盈则与时而息，虚则与时而消。天地日月，尚不能久，况於人与鬼神，而能长保其盈盛乎？勉令及时脩德，仍戒居存虑亡也。此辞先陈天地，后言人、鬼、神者，欲以轻譬重，亦先尊后卑也。而日月先天地者，承上“宜日中”之下，遂言其昃食，因举日月以对之，然后并陈天地，作文之体也。</p><h2 id="《象》曰-雷电皆至-丰。君子以折狱致刑。-​" tabindex="-1">《象》曰：雷电皆至，丰。君子以折狱致刑。 ​ <a class="header-anchor" href="#《象》曰-雷电皆至-丰。君子以折狱致刑。-​" aria-label="Permalink to “《象》曰：雷电皆至，丰。君子以折狱致刑。 ​”">​</a></h2><p>王弼：文明以动，不失情理也。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“雷电皆至，丰”者，雷者，天之威动，电者，天之光耀。雷电俱至，则威明备，足以为丰也。“君子以折狱致刑”者，君子法象天威而用刑罚，亦当文明以动，折狱断决也。断决狱讼，须得虚实之情；致用刑罚，必得轻重之中。若动而不明，则淫滥斯及，故君子象於此卦而折狱致刑。</p><h2 id="初九-遇其配主-虽旬无咎-往有尚。-​" tabindex="-1">初九：遇其配主，虽旬无咎，往有尚。 ​ <a class="header-anchor" href="#初九-遇其配主-虽旬无咎-往有尚。-​" aria-label="Permalink to “初九：遇其配主，虽旬无咎，往有尚。 ​”">​</a></h2><p>王弼：处丰之初，其配在四，以阳適阳，以明之动，能相光大者也。旬，均也。虽均无咎，往有尚也。初、四俱阳爻，故曰“均”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“遇其配主”者，丰者，文明必动，尚乎光大者也。初配在四，俱是阳爻以阳適阳以明之动能相光大者，也。故曰：“遇其配主也。虽旬无咎往有尚者，旬均也，俱是阳爻，谓之为均，非是阴阳相应，嫌其有咎，以其能相光大，故虽均，可以无咎，而往有嘉尚也，故曰“虽均无咎，往有尚”也。</p><h3 id="《象》曰-虽旬无咎-过旬灾也。-​" tabindex="-1">《象》曰：“虽旬无咎”，过旬灾也。 ​ <a class="header-anchor" href="#《象》曰-虽旬无咎-过旬灾也。-​" aria-label="Permalink to “《象》曰：“虽旬无咎”，过旬灾也。 ​”">​</a></h3><p>王弼：过均则争，交斯叛也。</p><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>“象曰”至“灾也”。○正义曰：“过旬灾光”者，言势若不均，则相倾夺。既相倾夺，则争竞乃兴，而相违背，灾咎至焉，故曰“过旬灾也”。○注“过均”至“叛也”。○正义曰：初，四应配，谓之为交，势若不均，则初、四之相交，於斯乖叛矣。</p><h2 id="六二-丰其蔀-日中见斗。往得疑疾-有孚发若-吉。-​" tabindex="-1">六二：丰其蔀，日中见斗。往得疑疾，有孚发若，吉。 ​ <a class="header-anchor" href="#六二-丰其蔀-日中见斗。往得疑疾-有孚发若-吉。-​" aria-label="Permalink to “六二：丰其蔀，日中见斗。往得疑疾，有孚发若，吉。 ​”">​</a></h2><p>王弼：蔀，覆暧，鄣光明之物也。处明动之时，不能自丰以光大之德，既处乎内，而又以阴居阴，所丰在蔀，幽而无睹者也，故曰“丰其蔀，日中见斗”也。日中者，明之盛也；斗见者，闇之极也。处盛明而丰其蔀，故曰“日中见斗”。不能自发，故往得疑疾。然履中当位，处闇不邪，有孚者也。若，辞也。有孚可以发其志，不困於闇，故获吉也。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>“六二丰其蔀”至“有孚发若吉”。○正义曰：“丰其蔀”者，二以阴居遥又处於内，幽闇无所睹见，所丰在於覆蔽，故曰“丰其蔀”也。蔀者，覆暧，障光明之物也。“日中见斗”者，二居离卦之中，如日正中，则至极盛者也。处日中盛明之时，而斗星显见，是二之至闇，使斗星见明者也。处光大之世，而为极闇之行，譬日中而斗星见，故曰“日中见斗”也。二、五俱阴，二巳见斗之闇，不能自发，以自求於五，往则得见疑之疾，故曰“往得疑疾”也。然居中履正，处闇不邪，是有信者也。有信以自发其志，不困於闇，故获吉也。故曰“有孚发若，吉”也。</p><h3 id="《象》曰-有孚发若-信以发志也。-​" tabindex="-1">《象》曰：“有孚发若”，信以发志也。 ​ <a class="header-anchor" href="#《象》曰-有孚发若-信以发志也。-​" aria-label="Permalink to “《象》曰：“有孚发若”，信以发志也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：信以发志者，虽处幽闇而不为邪，是有信以发其丰大之志，故得吉也。</p><h2 id="九三-丰其沛-日中见沬。折其右肱-无咎。-​" tabindex="-1">九三：丰其沛，日中见沬。折其右肱，无咎。 ​ <a class="header-anchor" href="#九三-丰其沛-日中见沬。折其右肱-无咎。-​" aria-label="Permalink to “九三：丰其沛，日中见沬。折其右肱，无咎。 ​”">​</a></h2><p>王弼：沛，幡幔，所以御盛光也。沬，微昧之明也。应在上六，志在乎阴，虽愈乎以阴处阴，亦未足以免於闇也。所丰在沛，日中则见沬之谓也。施明，则见沬而巳，施用，则折其右肱，故可以自守而巳，未足用也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“丰其沛，日中见沬”者，沛，幡幔，所以御盛光也。沬，微昧之明也，以九三应在上六，志在乎阴，虽愈於六二以阴处阴，亦未见免於闇也，是所以“丰在沛，日中见沬”。夫处光大之时，而丰沛见沬，虽愈於丰蔀见斗，然施於大事，终不可用。假如折其右肱，自守而巳，乃得无咎，故曰“折其右肱，无咎”。</p><h3 id="《象》曰-丰其沛-不可大事也。-​" tabindex="-1">《象》曰：丰其沛，不可大事也。 ​ <a class="header-anchor" href="#《象》曰-丰其沛-不可大事也。-​" aria-label="Permalink to “《象》曰：丰其沛，不可大事也。 ​”">​</a></h3><p>王弼：明不足也。</p><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“不可大事”者，当光大之时，可为大事，明不足，故不可为大事也。</p><h3 id="折其右肱-终不可用也。-​" tabindex="-1">折其右肱，终不可用也。 ​ <a class="header-anchor" href="#折其右肱-终不可用也。-​" aria-label="Permalink to “折其右肱，终不可用也。 ​”">​</a></h3><p>王弼：虽有左在，不足用也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“终不可用”者，凡用事在右肱，右肱既折，虽有左在，终不可用也。</p><h2 id="九四-丰其蔀-日中见斗。遇其夷主-吉。-​" tabindex="-1">九四：丰其蔀，日中见斗。遇其夷主，吉。 ​ <a class="header-anchor" href="#九四-丰其蔀-日中见斗。遇其夷主-吉。-​" aria-label="Permalink to “九四：丰其蔀，日中见斗。遇其夷主，吉。 ​”">​</a></h2><p>王弼：以阳居阴，丰其蔀也。得初以发，夷主吉也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“丰其蔀”者，九四以阳居阴，闇同於六二，故曰“丰其蔀”也。“日中见斗，遇其夷主，吉”者，夷，平也。四应在初，而同是阳爻，能相显发，而得其吉，故曰“遇其夷主，吉”也。言四之与初交相为主者，若宾主之义也。若据初適四，则以四为主，故曰“遇其配主”。自四之初，则以初为主，故曰“遇其夷主”也。二阳体敌，两主均平，故初谓四为“旬”，而四谓初为“夷”也。</p><h3 id="《象》曰-丰其蔀-位不当也。-日中见斗-幽不明也。-遇其夷主-吉行也。-​" tabindex="-1">《象》曰：“丰其蔀”，位不当也。“日中见斗”，幽不明也。“遇其夷主”，吉行也。 ​ <a class="header-anchor" href="#《象》曰-丰其蔀-位不当也。-日中见斗-幽不明也。-遇其夷主-吉行也。-​" aria-label="Permalink to “《象》曰：“丰其蔀”，位不当也。“日中见斗”，幽不明也。“遇其夷主”，吉行也。 ​”">​</a></h3><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“位不当”者，止谓以阳居阴，而位不当，所以丰蔀而闇者也。“幽不明也”者，日中盛则反而见斗，以譬当光大而居阴，是应明而幽闇不明也。“吉行也”者，处於阴位，为闇巳甚，更应於阴，无由获吉，犹与阳相遇，故得吉行也。</p><h2 id="六五-来章有庆誉-吉。-​" tabindex="-1">六五：来章有庆誉，吉。 ​ <a class="header-anchor" href="#六五-来章有庆誉-吉。-​" aria-label="Permalink to “六五：来章有庆誉，吉。 ​”">​</a></h2><p>王弼：以阴之质，来適尊阳之位，能自光大，章显其德，获庆誉也。</p><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：六五处丰大之世，以阴柔之质，来適尊阳之位，能自光大，章显其德，而获庆善也。故曰“来章有庆誉，吉”也。</p><h3 id="《象》曰-六五之吉-有庆也。-​" tabindex="-1">《象》曰：六五之吉，有庆也。 ​ <a class="header-anchor" href="#《象》曰-六五之吉-有庆也。-​" aria-label="Permalink to “《象》曰：六五之吉，有庆也。 ​”">​</a></h3><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“有庆也”者，言六五以柔处尊，履得其中，故致庆誉也。</p><h2 id="上六-丰其屋-蔀其家-闚其户-阒其无人。三岁不觌-凶。-​" tabindex="-1">上六：丰其屋，蔀其家，闚其户，阒其无人。三岁不觌，凶。 ​ <a class="header-anchor" href="#上六-丰其屋-蔀其家-闚其户-阒其无人。三岁不觌-凶。-​" aria-label="Permalink to “上六：丰其屋，蔀其家，闚其户，阒其无人。三岁不觌，凶。 ​”">​</a></h2><p>王弼：屋，藏荫之物，以阴处极而最在外，不履於位，深自幽隐，绝迹深藏者也。既丰其屋，又蔀其家，屋厚家覆，闇之甚也。虽闚其户，阒其无人，弃其所处，而自深藏也。处於明动尚大之，时而深自幽隐，以高其行；大道既济，而犹不见，隐不为贤，更为反道，凶其宜也。三年，丰道之成。治道未济，隐犹可也；既济而隐，是以治为乱者也。</p><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>“上六丰其屋”至“不觌”。○正义曰：屋者，藏荫隐蔽之物也。上六，以阴处阴，极以处外，不履於位，是深自幽隐，绝迹深藏也。事同丰厚於屋者也。既丰厚其屋，而又覆鄣其家，屋厚家闇，蔽鄣之甚也。虽闚视其户，而阒寂无人，弃其所处，而自深藏也。处於丰大之世，隐不为贤。治道未济，隐犹可也；三年丰道巳成，而犹不见，所以为凶，故曰“丰其屋，蔀其家，闚其户，阒其无人，三岁不觌，凶”。</p><h3 id="《象》曰-丰其屋-天际翔也。-​" tabindex="-1">《象》曰：“丰其屋”，天际翔也。 ​ <a class="header-anchor" href="#《象》曰-丰其屋-天际翔也。-​" aria-label="Permalink to “《象》曰：“丰其屋”，天际翔也。 ​”">​</a></h3><p>王弼：翳光最甚者也。</p><h3 id="疏-19" tabindex="-1">疏 <a class="header-anchor" href="#疏-19" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“天祭翔也”者，如鸟之飞翔於天际，言隐翳之深也。</p><h3 id="闚其户-阒其无人-自藏也。-​" tabindex="-1">“闚其户，阒其无人”，自藏也。 ​ <a class="header-anchor" href="#闚其户-阒其无人-自藏也。-​" aria-label="Permalink to ““闚其户，阒其无人”，自藏也。 ​”">​</a></h3><p>王弼：可以出而不出，自藏之谓也，非有为而藏。不出户庭，失时致凶，况自藏乎？凶其宜也。</p><h3 id="疏-20" tabindex="-1">疏 <a class="header-anchor" href="#疏-20" aria-label="Permalink to “疏”">​</a></h3><p>正义曰：“自藏也”者，言非有为而当自藏，可以出而不出，无事自为隐藏也。</p>',85)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
